from typing import List, Dict, Union

def extract_media_urls(tweets: List[Dict[str, Union[str, Dict[str, List[str]]]], hashtag: str) -> List[str]:
    media_urls = []
    for tweet in tweets:
        if hashtag in tweet["text"]:
            media_urls.extend(tweet["entities"]["media"])
    return media_urls
