import javax.ws.rs.core.Response;

public class ErrorResponseHandler {
    public Response errorResponse(int statusCode, String message) {
        switch (statusCode) {
            case 400:
                return Response.status(400).entity(new Message(message)).build();
            case 401:
                return Response.status(401).entity(new Message(message)).build();
            case 403:
                return Response.status(403).entity(new Message(message)).build();
            case 404:
                return Response.status(404).entity(new Message(message)).build();
            default:
                return Response.status(500).entity(new Message(message)).build();
        }
    }

    private static class Message {
        private String message;

        public Message(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }
}
```

