```swift
struct Locations {
    var position: Int

    init(position: Int) {
        self.position = position
    }

    init(json: String) throws {
        guard let data = json.data(using: .utf8) else {
            throw JSONError.invalidData
        }

        let jsonObject = try JSONSerialization.jsonObject(with: data, options: [])

        guard let jsonDict = jsonObject as? [String: Any],
              let position = jsonDict["position"] as? Int else {
            throw JSONError.invalidFormat
        }

        self.position = position
    }

    var json: String {
        let jsonDict: [String: Any] = ["position": position]

        do {
            let jsonData = try JSONSerialization.data(withJSONObject: jsonDict, options: [])
            if let jsonString = String(data: jsonData, encoding: .utf8) {
                return jsonString
            }
        } catch {
            return "{}"
        }

        return "{}"
    }
}

enum JSONError: Error {
    case invalidData
    case invalidFormat
}
```

In the solution, the `init(json: String)` method uses `JSONSerialization` to parse the JSON string and initialize the `Locations` instance. It checks for the presence of the `position` field and throws appropriate errors if the JSON is invalid or missing required fields.

