class Stack<T> {
    private var elements: [T] = []

    func push(_ element: T) {
        elements.append(element)
    }

    func pop() -> T? {
        return elements.popLast()
    }

    func peek() -> T? {
        return elements.last
    }

    func isEmpty() -> Bool {
        return elements.isEmpty
    }
}

// Example usage
var stack = Stack<Int>()
stack.push(5)
stack.push(10)
print(stack.peek())  // Output: Optional(10)
print(stack.pop())   // Output: Optional(10)
print(stack.isEmpty())  // Output: false
print(stack.pop())   // Output: Optional(5)
print(stack.isEmpty())  // Output: true
```

