class CustomIterator:
    def __init__(self, *args):
        self.args = args
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.index < len(self.args):
            result = self.args[self.index]
            self.index += 1
            return result
        else:
            raise StopIteration

# Example usage
# Create an iterator with a list of arguments
iterator1 = CustomIterator(1, 2, 3, 4, 5)
