# middleware.py
from django.http import HttpResponseForbidden
from .models import Article

class EditRestrictionMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        if request.path.startswith('/wiki/locked/edit/'):
            article_id = request.path.split('/')[-3]  # Extract article ID from the URL
            article = Article.objects.get(id=article_id)
            if article.is_locked and not request.user.is_staff:
                return HttpResponseForbidden("You do not have permission to edit this locked article.")
        return self.get_response(request)
```

In this solution, the `EditRestrictionMiddleware` checks if the requested URL is for editing a locked article. If so, it retrieves the article's status from the database and verifies if the user is a staff member. If the article is locked and the user is not a staff member, a 403 Forbidden response is returned, preventing the user from editing the article.

This middleware should be added to the Django settings to take effect. Similar logic can be implemented using other Python web frameworks by intercepting requests and checking the article's lock status and user's role before allowing the edit operation.

