import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.element.Element;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import java.util.Set;

@SupportedAnnotationTypes({"Repository", "Primary"})
public class CustomAnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (TypeElement annotation : annotations) {
            Set<? extends Element> annotatedElements = roundEnv.getElementsAnnotatedWith(annotation);
            for (Element element : annotatedElements) {
                if (annotation.getSimpleName().toString().equals("Repository")) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.NOTE, "Found @Repository annotated class: " + element.toString());
                } else if (annotation.getSimpleName().toString().equals("Primary")) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.NOTE, "Found @Primary annotated class: " + element.toString());
                }
            }
        }
        return true;
    }
}
```

This annotation processor extends `AbstractProcessor` and overrides the `process` method to handle the processing of annotated classes. It uses the `RoundEnvironment` to get the annotated elements and the `Messager` to print diagnostic messages. The `SupportedAnnotationTypes` annotation specifies the annotations that this processor supports. When the processor runs, it iterates through the annotated elements and prints messages based on the annotation type found.

