import csv

def calculate_fg_percentage(csv_file):
    team_fg_percentages = {}
    with open(csv_file, 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            team_name = row["Team Name"]
            fg_percentage = float(row["FG%"])
            if team_name in team_fg_percentages:
                team_fg_percentages[team_name].append(fg_percentage)
            else:
                team_fg_percentages[team_name] = [fg_percentage]

    average_fg_percentages = {}
    for team, percentages in team_fg_percentages.items():
        average_fg = sum(percentages) / len(percentages)
        average_fg_percentages[team] = round(average_fg, 2)

    return average_fg_percentages

# Example usage
