class AnimationSystem {
    private animations: Map<string, Animation>;
    private stage: Stage;

    constructor(stage: Stage) {
        this.animations = new Map();
        this.stage = stage;
    }

    addAnimation(anim: Animation, animName: string) {
        this.animations.set(animName, anim);
    }

    playAnimation(animName: string) {
        const anim = this.animations.get(animName);
        if (anim) {
            anim.play();
        } else {
            console.log(`Animation with name ${animName} not found`);
