class DataManager:
    def __init__(self):
        self.data = []

    def add_data_point(self, parameters):
        self.data.append(parameters)

    def average(self, attribute_index):
        total = sum(data[attribute_index] for data in self.data)
        return total / len(self.data) if self.data else 0

    def max_data_point(self, attribute_index):
        if not self.data:
            return None
        return max(self.data, key=lambda x: x[attribute_index])
