function validateEventForm() {
  var dateInput = document.getElementById('date').value;
  var startInput = document.getElementById('start').value;
  var endInput = document.getElementById('end').value;

  var dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  var timeRegex = /^(0[1-9]|1[0-2]):[0-5][0-9]$/;

  if (!dateInput.match(dateRegex)) {
    alert('Please enter a valid date in the format YYYY-MM-DD');
    return false;
  }

  if (!startInput.match(timeRegex)) {
    alert('Please enter a valid start time in the format HH:MM (12-hour format)');
    return false;
  }

  if (!endInput.match(timeRegex)) {
    alert('Please enter a valid end time in the format HH:MM (12-hour format)');
    return false;
  }

  var startTime = new Date('2000-01-01T' + startInput + ':00');
  var endTime = new Date('2000-01-01T' + endInput + ':00');

  if (endTime <= startTime) {
    alert('End time must be later than the start time');
    return false;
  }

  document.getElementById('eventForm').submit();
  return true;
}
```

