        existingFeedback.parentNode.removeChild(existingFeedback);
    }
    feedbackElement.id = 'validationFeedback';
    this.parentNode.appendChild(feedbackElement);
});

// Function to validate email format
function isValidEmail(email) {
    // Regular expression for email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

// Function to validate username format
function isValidUsername(username) {
    // Regular expression for username validation (e.g., alphanumeric characters only)
    const usernameRegex = /^[a-zA-Z0-9]+$/;
