class TriggerAsAxis : Combinator<bool, bool, float> {
  public TriggerAsAxis(TriggerInput positive, TriggerInput negative) : base(positive, negative, Calculate) { }

  private static float Calculate(bool positive, bool negative) {
    if (positive && !negative) {
      return 1.0f;
    } else if (!positive && negative) {
      return -1.0f;
    } else {
      return 0.0f;
    }
  }
}

class CombineScalars : Combinator<float, float, Vector2> {
  public CombineScalars(ScalarInput x, ScalarInput y) : base(x, y, Combine) { }

  private static Vector2 Combine(float x, float y) {
    return new Vector2(x, y);
  }
}
