    initial_sum = sum(random.choices(range(1, 7), k=2))  # Simulate the initial dice roll
    if initial_sum in (7, 11):
        return "Player wins with the initial sum of {}".format(initial_sum)
    elif initial_sum in (2, 3, 12):
        return "Player loses with the initial sum of {}".format(initial_sum)
