function convertToCSSString(styleObject) {
    const cssString = Object.entries(styleObject)
        .map(([key, value]) => {
            const cssProperty = key.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
            const cssValue = typeof value === 'number' ? (value === 0 ? '0' : value + 'px') : value;
            return `${cssProperty}: ${cssValue};`;
        })
        .join('\n');
    return cssString;
}

