from django.contrib.auth import authenticate, login
from django.http import JsonResponse, HttpResponseBadRequest, HttpResponseRedirect
from django.urls import reverse

def login_view(request):
    if request.user.is_authenticated:
        return HttpResponseRedirect(reverse('home'))  # Redirect to home page if user is already authenticated

    if request.method == 'POST':
        username = request.POST.get('username')
        password = request.POST.get('password')
        user = authenticate(request, username=username, password=password)

        if user is not None:
            login(request, user)
            return JsonResponse({'success': True, 'message': 'Login successful'})
        else:
            return JsonResponse({'success': False, 'message': 'Invalid username or password'}, status=401)
    else:
        return HttpResponseBadRequest('Invalid request method')
```

In this solution, the `login_view` function checks if the user is already authenticated and redirects them to the home page if they are. For POST requests, it attempts to authenticate the user using the provided username and password. If the authentication is successful, it logs the user in and returns a JSON response indicating success. If the authentication fails, it returns a JSON response with an error message and a 401 status code. Any other request method results in a 400 Bad Request response.

