import re

def count_license_comments(file_path):
    with open(file_path, 'r') as file:
        source_code = file.read()

    single_line_comments = re.findall(r'//.*?$', source_code, re.MULTILINE)
    multi_line_comments = re.findall(r'/\*.*?\*/', source_code, re.DOTALL)

    keywords_count = {
        'Redistribution': 0,
        'Use': 0,
        'Modification': 0
    }

    for comment in single_line_comments + multi_line_comments:
        for keyword in keywords_count:
            if keyword.lower() in comment.lower():
                keywords_count[keyword] += 1

    for keyword, count in keywords_count.items():
        print(f'{keyword}: {count}')

# Example usage
count_license_comments('source_code_file.cpp')
```

