class Route:
    def __init__(self, path, method, handler):
        self.path = path
        self.method = method
        self.handler = handler

    def match(self, request_path, request_method):
        return self.path == request_path and self.method == request_method


class Router:
    def __init__(self):
        self.routes = []

    def add_route(self, path, method, handler):
        self.routes.append(Route(path, method, handler))

    def match_route(self, request_path, request_method):
        for route in self.routes:
            if route.match(request_path, request_method):
                return route.handler
        return None


def hello_world():
