    queue.0.push("Message 1".to_string());
    queue.0.push("Message 2".to_string());
    queue.0.push("Message 3".to_string());

    let app = Application::new();

    while let Some(msg) = queue.pop() {
        app.__dispatch(msg, &mut queue);
        while let Some(msg) = queue.pop() {
            app.__dispatch(msg, &mut queue);
        }
        app.__render(&mut queue);
    }

    app.ready(true);
}
