import AVFoundation

class VideoRecorder {
    private let session = AVCaptureSession()
    private let fileOutput = AVCaptureMovieFileOutput()

    func startRecording() {
        session.beginConfiguration()

        guard let device = AVCaptureDevice.default(for: .video) else { return }

