import subprocess
import time
import signal
import os

def start_web_server(start_command):
    subprocess.Popen(start_command, shell=True)

def check_web_server(port):
    try:
        response = subprocess.check_output(f"curl -Is http://localhost:{port} | head -n 1", shell=True)
        return "200 OK" in response.decode("utf-8")
    except subprocess.CalledProcessError:
        return False

def restart_web_server(start_command):
    os.system(f"pkill -f '{start_command}'")
    start_web_server(start_command)

def monitor_web_server(start_command, port, timeout):
    start_web_server(start_command)
    while True:
        if not check_web_server(port):
            restart_web_server(start_command)
        time.sleep(timeout)

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 4:
        print("Usage: python web_server_monitor.py <start_command> <port> <timeout>")
        sys.exit(1)
    start_command = sys.argv[1]
    port = sys.argv[2]
    timeout = int(sys.argv[3])
    monitor_web_server(start_command, port, timeout)
```

