func consumeAndValidateTypeFor(dictionary: inout [String: Any], parentPropertyName: String) throws {
    for (key, value) in dictionary {
        switch value {
        case is String, is Int, is Double, is Bool, is [Any], is [String: Any]:
            if let nestedDictionary = value as? [String: Any] {
                try consumeAndValidateTypeFor(dictionary: &nestedDictionary, parentPropertyName: key)
            }
        default:
            throw TypeMismatchError(propertyName: key, parentPropertyName: parentPropertyName, expectedType: type(of: value))
        }
    }
}

struct TypeMismatchError: Error {
    let propertyName: String
    let parentPropertyName: String
    let expectedType: Any.Type

