public class CategoryCategorizer {
    private enum Category {
        K1(new BigDecimal("2.72"), new BigDecimal("12.04")),
        K2(new BigDecimal("12.05"), new BigDecimal("20.23")),
        K3(new BigDecimal("20.28"), new BigDecimal("32.42")),
