function validateNamespaceDeclaration(string $code): bool {
    $lines = explode("\n", $code);
    $strictTypesFound = false;
    $namespaceFound = false;

    foreach ($lines as $line) {
        $trimmedLine = trim($line);
        if (strpos($trimmedLine, 'declare(strict_types=1);') === 0) {
            $strictTypesFound = true;
        } elseif (strpos($trimmedLine, 'namespace ') === 0) {
            if ($strictTypesFound && preg_match('/^namespace\s+[a-zA-Z_\x7f-\xff][a-zA-Z0-9_\x7f-\xff\\\\]*;/', $trimmedLine)) {
                $namespaceFound = true;
            } else {
                return false;
            }
        } elseif ($strictTypesFound && $namespaceFound && $trimmedLine !== '') {
            return false; // Additional code after valid namespace declaration
        }
    }

    return $strictTypesFound && $namespaceFound;
}
