func calculatePolygonArea(_ vertices: [(Double, Double)]) -> Double {
    var area = 0.0
    let n = vertices.count
    for i in 0..<n {
        let j = (i + 1) % n
        area += (vertices[i].0 * vertices[j].1) - (vertices[i].1 * vertices[j].0)
    }
    return abs(area) / 2.0
}
```

