Use the provided code snippet as a reference to understand the peripherals' access and the UART module's usage.

```rust
const EXCEPTION_MESSAGES: [&str; 8] = [
    "Instruction address misaligned", // 0
    "Instruction access fault",       // 1
    "Illegal instruction",            // 2
    "Breakpoint",                     // 3
    "Load address misaligned",        // 4
    "Load access fault",              // 5
    "Store/AMO address misaligned",   // 6
    "Store/AMO access fault",         // 7
];

fn send_exception_report(exception_code: u8) {
    // Access the system peripherals
    let dp = unsafe { pac::Peripherals::steal() };

    // Print header for exception report
    for &byte in "Exception:\r\n\t".as_bytes() {
        while dp.UART.uart_fifo_config_1.read().tx_fifo_cnt().bits() < 1 {}
        dp.UART.uart_fifo_data.write(|w| w.data().bits(byte));
    }

    // Send exception message over UART
    let message = EXCEPTION_MESSAGES.get(exception_code as usize).unwrap_or(&"Unknown exception");
    for &byte in message.as_bytes() {
        while dp.UART.uart_fifo_config_1.read().tx_fifo_cnt().bits() < 1 {}
        dp.UART.uart_fifo_data.write(|w| w.data().bits(byte));
    }
}
```

