from typing import List

def escapeGhosts(ghosts: List[List[int]], target: List[int]) -> bool:
    player_distance = abs(target[0]) + abs(target[1])  # Manhattan distance from player to target

    for ghost in ghosts:
        ghost_distance = abs(target[0] - ghost[0]) + abs(target[1] - ghost[1])  # Manhattan distance from ghost to target
        if ghost_distance <= player_distance:
            return False  # Player can be caught by this ghost

    return True  # Player can reach the target without being caught by any ghosts
