```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class License {
    String licenseId;
    String softwarePackage;
    String licenseType;

    public License(String licenseId, String softwarePackage, String licenseType) {
        this.licenseId = licenseId;
        this.softwarePackage = softwarePackage;
        this.licenseType = licenseType;
    }
}

class LicenseManager {
    List<License> licenses;

    public LicenseManager() {
        licenses = new ArrayList<>();
    }

    public void addLicense(String licenseId, String softwarePackage, String licenseType) {
        for (License license : licenses) {
            if (license.licenseId.equals(licenseId)) {
                license.softwarePackage = softwarePackage;
                license.licenseType = licenseType;
                return;
            }
        }
        licenses.add(new License(licenseId, softwarePackage, licenseType));
        Collections.sort(licenses, (l1, l2) -> l1.licenseId.compareTo(l2.licenseId));
    }

    public void removeLicense(String licenseId) {
        licenses.removeIf(license -> license.licenseId.equals(licenseId));
    }

    public List<String> displayLicenses() {
        List<String> result = new ArrayList<>();
        for (License license : licenses) {
            result.add("License ID: " + license.licenseId + ", Software Package: " + license.softwarePackage + ", License Type: " + license.licenseType);
        }
        return result;
    }
}
