// map.rs
pub mod map {
    pub struct Map<K, V> {
        data: std::collections::HashMap<K, V>,
    }

    impl<K, V> Map<K, V> {
        pub fn new() -> Self {
            Map {
                data: std::collections::HashMap::new(),
            }
        }

        pub fn insert(&mut self, key: K, value: V) {
            self.data.insert(key, value);
        }

        pub fn get(&self, key: &K) -> Option<&V> {
            self.data.get(key)
        }
    }
}

// list.rs
pub mod list {
    pub struct List<T> {
        data: Vec<T>,
    }

    impl<T> List<T> {
        pub fn new() -> Self {
            List { data: Vec::new() }
        }

        pub fn push(&mut self, value: T) {
            self.data.push(value);
        }

        pub fn get(&self, index: usize) -> Option<&T> {
            self.data.get(index)
        }
    }
}

// tuple.rs
pub mod tuple {
    pub struct Tuple<T> {
        data: Vec<T>,
    }

    impl<T> Tuple<T> {
        pub fn new(data: Vec<T>) -> Self {
            Tuple { data }
        }

        pub fn get(&self, index: usize) -> Option<&T> {
            self.data.get(index)
        }
    }
}
```

In this solution, we have implemented a module system for the map, list, and tuple data types in Rust. Each module encapsulates the corresponding data type and provides the necessary functionality for manipulation and access. The map module provides functions for key-value pair manipulation, the list module offers functions for list manipulation and access, and the tuple module provides functions for tuple creation and access. Each module is designed to be easily integrated into a larger codebase, ensuring modularity and encapsulation.

