def find_closest_value(conv_S, y, TOL):
    closest_value = None
    min_distance = float('inf')

    for value in conv_S:
        if value > TOL:
            distance = abs(value - y)
            if distance < min_distance:
                min_distance = distance
                closest_value = value

    return closest_value
```

