```python
import numpy as np
import random

class NeuralNetwork:
    def __init__(self, network, mutation_chance):
        self.network = network
        self.mutation_chance = mutation_chance

    def mutate_network(self):
        for a, layer in enumerate(self.network):
            for b, neuron_weights in enumerate(layer['weights']):
                for c, weight in enumerate(neuron_weights):
                    if self.mutation_chance >= np.random.random():
                        self.network[a]['weights'][b][c] = random.uniform(-1, 1)
            for b, element in enumerate(layer['biases']):
                if self.mutation_chance >= np.random.random():
                    self.network[a]['biases'][b] = np.random.random()
