import json

def convert_to_json_string(data: dict) -> str:
    def remove_none_values(d):
        return {k: v for k, v in d.items() if v is not None}

    def convert_nested_dicts(d):
        for k, v in d.items():
            if isinstance(v, dict):
                d[k] = convert_nested_dicts(v)
        return d

    cleaned_data = remove_none_values(data)
    cleaned_data = convert_nested_dicts(cleaned_data)
    return json.dumps(cleaned_data, indent=4)
