class CustomFileSystem
{
    private $basePath;

    public function __construct($basePath)
    {
        $this->basePath = $basePath;
    }

    public function copyFile($source, $destination)
    {
        $sourcePath = $this->basePath . '/' . $source;
        $destinationPath = $this->basePath . '/' . $destination;

        if (file_exists($sourcePath)) {
            if (!file_exists(dirname($destinationPath))) {
                mkdir(dirname($destinationPath), 0777, true);
            }
            if (copy($sourcePath, $destinationPath)) {
                return "File copied successfully.";
            } else {
                return "Failed to copy the file.";
            }
        } else {
            return "Source file does not exist.";
        }
    }

    public function findCommand($commandName)
    {
        $commandPath = $this->basePath . '/' . $commandName;
        if (file_exists($commandPath)) {
            return "Command found at: " . $commandPath;
        } else {
            return "Command not found.";
        }
    }
}

// Usage
