import java.time.Duration;
import java.time.LocalDateTime;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;

public class SleepStartEvent {
    private Long resourceId;
    private Duration sleepDuration;
    private LocalDateTime failUntil;
    private CompletionStage<AcceptResult> accepted;

    public SleepStartEvent(Long resourceId, Duration sleepDuration, LocalDateTime failUntil, CompletionStage<AcceptResult> accept) {
        this.resourceId = resourceId;
        this.sleepDuration = sleepDuration;
        this.failUntil = failUntil;
        this.accepted = accept;
    }

    public static SleepStartEvent neverFail(Long resourceId, Duration sleepDuration) {
        CompletableFuture<AcceptResult> alwaysAccepted = CompletableFuture.completedFuture(AcceptResult.SUCCESS);
        return new SleepStartEvent(resourceId, sleepDuration, LocalDateTime.MAX, alwaysAccepted);
    }
}

enum AcceptResult {
    SUCCESS,
    FAILURE
}
```

