class KeyValueStringHandler:
    def __init__(self):
        self.key_value_pairs = {}

    def parse_string(self, input_string):
        pairs = input_string.split(',')
        for pair in pairs:
            key, value = pair.split('=')
            if '{' in value and '}' in value:
                nested_key_value = value.strip('{}').split(',')
                nested_dict = {}
                for nested_pair in nested_key_value:
                    nested_key, nested_value = nested_pair.split('=')
                    nested_dict[nested_key] = nested_value
                self.key_value_pairs[key] = nested_dict
            else:
                self.key_value_pairs[key] = value

    def to_string(self):
        result = []
        for key, value in self.key_value_pairs.items():
            if isinstance(value, dict):
                nested_string = ','.join([f"{k}={v}" for k, v in value.items()])
                result.append(f"{key}={{{nested_string}}}")
            else:
                result.append(f"{key}={value}")
        return ','.join(result)

# Test case
class TestKeyValueStringHandler(unittest.TestCase):
    def test_parse_string(self):
        handler = KeyValueStringHandler()
        input_string = "key1=value1,key2={nested_key1=nested_value1,nested_key2=nested_value2},key3=value3"
        handler.parse_string(input_string)
        expected_output = {
            'key1': 'value1',
            'key2': {'nested_key1': 'nested_value1', 'nested_key2': 'nested_value2'},
            'key3': 'value3'
        }
        self.assertEqual(handler.key_value_pairs, expected_output)

    def test_to_string(self):
        handler = KeyValueStringHandler()
        handler.key_value_pairs = {
            'key1': 'value1',
            'key2': {'nested_key1': 'nested_value1', 'nested_key2': 'nested_value2'},
            'key3': 'value3'
        }
        expected_output = "key1=value1,key2={nested_key1=nested_value1,nested_key2=nested_value2},key3=value3"
        self.assertEqual(handler.to_string(), expected_output)

if __name__ == '__main__':
    unittest.main()
```

In the solution, the `KeyValueStringHandler` class is implemented with methods to parse a string into key-value pairs and to convert key-value pairs into a string. The class also handles nested key-value pairs within the string. Additionally, a test case using `unittest` is provided to validate the functionality of the `KeyValueStringHandler` class.

