acc_num1 = bank.create_account("Alice", 1000)
acc_num2 = bank.create_account("Bob", 500)
bank.deposit(acc_num1, 500)
bank.withdraw(acc_num2, 200)
print(bank.balance_inquiry(acc_num1))  # Output: 1500
