import json

def read_schemas(files):
    schema_data = {}
    for file in files:
        try:
            with open(file, 'r') as f:
                schema_data[file] = json.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"Schema file '{file}' not found")
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON format in schema file '{file}'")
    return schema_data

def generate_report(files, output):
    try:
        schema_data = read_schemas(files)
        with open(output, 'w') as report_file:
            for file, schema in schema_data.items():
                report_file.write(f"Schema File: {file}\n")
                report_file.write(f"Total Number of Fields: {len(schema)}\n")
                report_file.write("Fields:\n")
                for field, details in schema.items():
                    report_file.write(f"- {field}: {details['type']}")
                    if 'constraints' in details:
                        report_file.write(f" ({', '.join(details['constraints'])})")
                    report_file.write("\n")
                report_file.write("\n")
    except FileNotFoundError as e:
        print(e)
    except ValueError as e:
        print(e)

# Example usage
