import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public class OrganizationSnapshot {
    private Map<String, Object> organizationData;
    private Map<String, Map<String, Object>> snapshots;

    public OrganizationSnapshot(Map<String, Object> initialData) {
        this.organizationData = new HashMap<>(initialData);
        this.snapshots = new HashMap<>();
    }

    public String takeSnapshot() {
        String snapshotId = UUID.randomUUID().toString();
        snapshots.put(snapshotId, new HashMap<>(organizationData));
        return snapshotId;
    }

    public Map<String, Object> getSnapshot(String snapshotId) {
        return snapshots.getOrDefault(snapshotId, new HashMap<>());
    }
}
```

